// isVisible reports whether a proto element carrying the given VisibilityRule
// should be included in generated output.
//
// A nil rule means the element carries no `google.api.*_visibility`
// annotation, so it is always visible. Otherwise the rule's restriction is
// split on commas and the element is visible if any trimmed label matches one
// of the visibility restriction selectors configured on the registry. If no
// label matches — including the case where no selectors are configured at all
// — the element is hidden.
func isVisible(r *visibility.VisibilityRule, reg *descriptor.Registry) bool {
	if r == nil {
		return true
	}

	selectors := reg.GetVisibilityRestrictionSelectors()
	for _, restriction := range strings.Split(r.GetRestriction(), ",") {
		if selectors[strings.TrimSpace(restriction)] {
			return true
		}
	}
	return false
}

// fieldVisibility extracts the google.api.field_visibility VisibilityRule from
// a field's options, or nil if the annotation is absent.
func fieldVisibility(fd *descriptor.Field) *visibility.VisibilityRule {
