func runVis(t *testing.T, selectors []string) map[string]any {
	t.Helper()
	req := loadRequest(t, "testdata/visibility.prototext")
	reg := descriptor.NewRegistry()
	reg.SetVisibilityRestrictionSelectors(selectors)
	if err := reg.Load(req); err != nil {
		t.Fatalf("load: %v", err)
	}
	var targets []*descriptor.File
	for _, name := range req.FileToGenerate {
		f, err := reg.LookupFile(name)
		if err != nil {
			t.Fatalf("lookup: %v", err)
		}
		targets = append(targets, f)
	}
	out, err := Generate(reg, targets)
	if err != nil {
		t.Fatalf("generate: %v", err)
	}
	if len(out) != 1 {
		t.Fatalf("want 1 file got %d", len(out))
	}
	var doc map[string]any
	if err := json.Unmarshal([]byte(out[0].GetContent()), &doc); err != nil {
		t.Fatalf("unmarshal: %v", err)
	}
	return doc
}

func TestScratchNoSelectors(t *testing.T) {
	doc := runVis(t, nil)
	b, _ := json.MarshalIndent(doc, "", "  ")
	t.Logf("NO SELECTORS:\n%s", string(b))
}

func TestScratchInternal(t *testing.T) {
	doc := runVis(t, []string{"INTERNAL"})
	paths, _ := doc["paths"].(map[string]any)
	if _, ok := paths["/v1/internal"]; !ok {
		t.Errorf("expected /v1/internal visible with INTERNAL selector")
	}
